{
  "name": "quota-gate",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "In-process quota gate with fair backpressure",
  "main": "src/index.js",
  "scripts": { "test": "node --test" },
  "engines": { "node": ">=20" }
}

content.content:
1	export class QuotaExceededError extends Error {
2	  constructor(code, message) {
3	    super(message);
4	    this.name = 'QuotaExceededError';
5	    this.code = code;
6	  }
7	}
8	
9	// Internal state of every gate, shared with child gates through a WeakMap so
10	// the public gate object keeps its exact shape.
11	const gateState = new WeakMap();
12	
13	// Monotonic counter that never repeats or moves backwards, independent of the
14	// (mocked, possibly frozen) wall clock; gives queued entries a global arrival
15	// order so reparented queues can merge fairly.
16	let enqueueSeq = 0;
17	
18	function assertInteger(value, name) {
19	  if (typeof value !== 'number' || !Number.isInteger(value)) {
20	    throw new TypeError(`${name} must be an integer`);
21	  }
22	}
23	
24	function assertSignal(signal) {
25	  if (
26	    signal !== undefined &&
27	    signal !== null &&
28	    (typeof signal !== 'object' ||
29	      typeof signal.addEventListener !== 'function' ||
30	      typeof signal.removeEventListener !== 'function')
31	  ) {
32	    throw new TypeError('signal must be an AbortSignal');
33	  }
34	}
35	
36	export function createGate({ limit, windowMs, maxWaitMs = 0, parent } = {}) {
37	  assertInteger(limit, 'limit');
38	  assertInteger(windowMs, 'windowMs');
39	  assertInteger(maxWaitMs, 'maxWaitMs');
40	  if (limit <= 0) throw new RangeError('limit must be a positive integer');
41	  if (windowMs <= 0) throw new RangeError('windowMs must be a positive integer');
42	  if (maxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');
43	
44	  let parentState = null;
45	  if (parent !== undefined && parent !== null) {
46	    parentState = gateState.get(parent);
47	    if (parentState === undefined) {
48	      throw new TypeError('parent must be a gate created by createGate');
49	    }
50	    if (limit > parentState.limit) {
51	      throw new RangeError('limit must not exceed parent limit');
52	    }
53	  }
54	
55	  const state = {
56	    limit,
57	    windowMs,
58	    maxWaitMs,
59	    parent: parentState,
60	    children: new Set(),
61	    isRoot: parentState === null,
62	    // Own-window accounting.
63	    ownGen: 0, // bumped on every own-window flip, invalidates old handles
64	    usedOwn: 0, // own units occupied or lent out in the current own window
65	    inFlight: 0, // units occupied through this gate and not yet cleared
66	    borrowedInFlight: 0, // units this gate's occupations borrowed, still live
67	    lentInFlight: 0, // own units lent to descendants' admitted occupations
68	    poolDraw: 0, // committed pool charge, valid only when drawGen === poolGen
69	    drawGen: -1,
70	    // Cross-gate reservation accounting. A pending acquireAll first reserves
71	    // the member's own current-window slice, then own slices up the direct
72	    // parent chain (each step registering the lend); the root pool covers the
73	    // remainder. Every gathered unit draws pool room until commit or rollback.
74	    //
75	    // A non-root gate's reserved units are pendingOwn + pendingLends: own
76	    // window units promised to pending combos, as member or as ancestor
77	    // lender. The root's reserved units are poolResvUnits: uncommitted units
78	    // drawn from the pool. Across the family every reserved unit counts once.
79	    rolledBack: 0, // failed whole-combo reservation attempts owned here
80	    pendingOwn: 0,
81	    pendingLends: 0,
82	    resvAsMember: new Set(), // entries holding pendingOwn here
83	    resvAsLender: new Set(), // entries holding pendingLends here
84	    lentLinks: new Set(), // admitted occupation links lent from this gate
85	    // Observability.
86	    waiting: 0, // units currently queued through this gate
87	    granted: 0,
88	    refused: 0,
89	    expired: 0,
90	    cancelled: 0,
91	    openHandles: new Set(),
92	    root: null,
93	    timer: null,
94	  };
95	
96	  let root;
97	  if (parentState === null) {
98	    root = state;
99	    // The quota pool shared by the whole hierarchy lives on the root gate.
100	    Object.assign(state, {
101	      poolLimit: limit,
102	      poolGen: 0, // bumped on every root-window flip
103	      poolUsed: 0, // units committed or reserved in the current pool window
104	      poolLinks: new Set(), // admitted pool borrows, reclaimed at the pool flip
105	      poolResv: new Set(), // uncommitted pool reservation links
106	      poolResvUnits: 0, // sum of units behind poolResv
107	      queue: [], // queued requests from every gate, in arrival order
108	      head: 0, // index of the first live entry; entries are never shifted
109	      liveQueued: 0, // entries not yet settled
110	      serveWave: 0, // monotonic count of serves that overtook a blocked combo
111	      minDeadline: Infinity, // earliest live deadline, skips idle sweeps
112	      lastNow: 0, // monotonic clock: never moves backwards
113	      members: new Set(),
114	    });
115	    state.members.add(state);
116	  } else {
117	    root = parentState.root;
118	    root.members.add(state);
119	    parentState.children.add(state);
120	  }
121	  state.root = root;
122	
123	  // Operational helpers read state.root dynamically rather than capturing the
124	  // local `root`: reparent() can move this gate (and its descendants) into
125	  // another family's pool.
126	  function now() {
127	    const r = state.root;
128	    const t = Date.now();
129	    if (t > r.lastNow) r.lastNow = t;
130	    return r.lastNow;
131	  }
132	
133	  function effectiveDraw(node) {
134	    return node.drawGen === node.root.poolGen ? node.poolDraw : 0;
135	  }
136	
137	  function chargeDraw(node, units) {
138	    if (node.drawGen !== node.root.poolGen) {
139	      node.drawGen = node.root.poolGen;
140	      node.poolDraw = 0;
141	    }
142	    node.poolDraw += units;
143	  }
144	
145	  function reservedOn(g) {
146	    return g === g.root ? g.root.poolResvUnits : g.pendingOwn + g.pendingLends;
147	  }
148	
149	  // --- Combo reservations ---------------------------------------------------
150	  //
151	  // seg:  { gate, units, own, ownReleased, links, gen }
152	  // link: { kind:'own'|'pool', lender, units, released, gen }
153	  //
154	  // Gather plans first and applies second, so a plan the pool cannot cover is
155	  // rejected without any mutation and the whole-combo rollback is trivial.
156	  // Sibling members share ancestor chains; the tentative `claimed` map debits
157	  // ancestor headroom cumulatively inside one plan. Every registration is
158	  // intrusive: commit, rollback and window-flip reclaims touch only the gates
159	  // involved, never the queue or the whole family.
160	
161	  function buildSegs(comboGates, unitsOf) {
162	    return comboGates.map((g) => ({
163	      gate: g,
164	      units: unitsOf(g),
165	      own: 0,
166	      ownReleased: false, // member own slice already reclaimed by an own flip
167	      links: [],
168	      gen: -1,
169	    }));
170	  }
171	
172	  function ownHeadroom(g, claimed) {
173	    return Math.max(0, g.limit - g.usedOwn - g.pendingOwn - g.pendingLends - (claimed.get(g) ?? 0));
174	  }
175	
176	  // Pure plan: fills seg.own / seg.links and returns total pool need. A
177	  // member slice larger than that gate's own limit simply borrows the excess
178	  // up the chain — member limits never cap a combo, only the root pool does.
179	  function planGather(segs) {
180	    const r = state.root;
181	    const claimed = new Map();
182	    let poolNeed = 0;
183	    for (const seg of segs) {
184	      const m = seg.gate;
185	      if (m === r) {
186	        seg.links.push({ kind: 'pool', lender: r, units: seg.units, released: false, gen: -1 });
187	        poolNeed += seg.units;
188	        continue;
189	      }
190	      let need = seg.units;
191	      const own = Math.min(need, ownHeadroom(m, claimed));
192	      seg.own = own;
193	      claimed.set(m, (claimed.get(m) ?? 0) + own);
194	      need -= own;
195	      let cur = m.parent;
196	      while (need > 0 && cur !== null && cur !== r) {
197	        const lend = Math.min(need, ownHeadroom(cur, claimed));
198	        if (lend > 0) {
199	          seg.links.push({ kind: 'own', lender: cur, units: lend, released: false, gen: -1 });
200	          claimed.set(cur, (claimed.get(cur) ?? 0) + lend);
201	          need -= lend;
202	        }
203	        cur = cur.parent;
204	      }
205	      if (need > 0) {
206	        seg.links.push({ kind: 'pool', lender: r, units: need, released: false, gen: -1 });
207	        poolNeed += need;
208	      }
209	    }
210	    return poolNeed;
211	  }
212	
213	  // Apply a planned reservation; the caller pre-checked poolNeed against room.
214	  function applyGather(entry, segs) {
215	    const r = entry.owner.root;
216	    const gen = r.poolGen;
217	    for (const seg of segs) {
218	      const m = seg.gate;
219	      seg.gen = gen;
220	      seg.ownReleased = false;
221	      if (m !== r && seg.own > 0) {
222	        m.pendingOwn += seg.own;
223	        m.resvAsMember.add(entry);
224	        r.poolUsed += seg.own;
225	      }
226	      for (const link of seg.links) {
227	        link.gen = gen;
228	        r.poolUsed += link.units;
229	        if (link.kind === 'own') {
230	          link.lender.pendingLends += link.units;
231	          link.lender.resvAsLender.add(entry);
232	        } else {
233	          r.poolResv.add(link);
234	          r.poolResvUnits += link.units;
235	          if (m === r) m.resvAsMember.add(entry);
236	        }
237	      }
238	    }
239	    entry.segs = segs;
240	    entry.holdsHeld = true;
241	  }
242	
243	  // Plan, check pool room, apply — or reject without touching anything. The
244	  // whole combo draws pool room: a member's own slice and every ancestor lend
245	  // are partitions OF the pool, not capacity beyond it. Feasibility is
246	  // therefore simply poolUsed + total combo units <= poolLimit; the plan's
247	  // own/lender/pool partition only decides which own window each unit lands
248	  // on (and thus where its flip reclaims it).
249	  function tryGather(entry, segs) {
250	    const r = entry.owner.root;
251	    let total = 0;
252	    for (const seg of segs) total += seg.units;
253	    if (r.poolUsed + total > r.poolLimit) {
254	      for (const seg of segs) {
255	        seg.own = 0;
256	        seg.links = [];
257	      }
258	      return false;
259	    }
260	    planGather(segs);
261	    applyGather(entry, segs);
262	    return true;
263	  }
264	
265	  // Same whole reservation for one gate: the entry's own current-window slice,
266	  // lends up the direct parent chain, then the root pool. A single-gate
267	  // occupation gathers exactly the way a one-member combo would — its own
268	  // limit never caps the request, only the family pool does.
269	  function tryGatherOne(entry, g, units) {
270	    return tryGather(entry, buildSegs([g], () => units));
271	  }
272	
273	  // Release a held reservation wholesale. Pool room is refunded only while
274	  // the charged pool window is still the current one; a pool flip already
275	  // reclaimed it (the link is marked released and its gen is stale).
276	  function releaseHolds(entry) {
277	    if (!entry.holdsHeld || entry.segs === null) return;
278	    const r = entry.owner.root;
279	    for (const seg of entry.segs) {
280	      const m = seg.gate;
281	      if (!seg.ownReleased && seg.own > 0) {
282	        seg.ownReleased = true;
283	        m.pendingOwn -= seg.own;
284	        m.resvAsMember.delete(entry);
285	        if (seg.gen === r.poolGen) r.poolUsed -= seg.own;
286	      }
287	      for (const link of seg.links) {
288	        if (link.released) continue;
289	        link.released = true;
290	        if (link.kind === 'pool') {
291	          // delete() reports whether the link still charged the pool: a pool
292	          // flip already cleared the set and zeroed poolResvUnits, so a stale
293	          // link must not subtract twice.
294	          if (r.poolResv.delete(link)) r.poolResvUnits -= link.units;
295	          m.resvAsMember.delete(entry);
296	        } else {
297	          link.lender.pendingLends -= link.units;
298	          link.lender.resvAsLender.delete(entry);
299	        }
300	        if (link.gen === r.poolGen) r.poolUsed -= link.units;
301	      }
302	    }
303	    entry.holdsHeld = false;
304	    entry.segs = null;
305	  }
306	
307	  // --- Handles --------------------------------------------------------------
308	  //
309	  // The handle exposes exactly one own property, release, as a closure: the
310	  // destructured method called without a receiver works the same. Every link
311	  // remembers the generations of both sides, so a release after either window
312	  // flipped never subtracts quota that flip already settled.
313	
314	  function makeHandle(records) {
315	    let active = true;
316	    return {
317	      release() {
318	        if (!active) return;
319	        active = false;
320	        for (const rec of records) {
321	          const seg = rec.seg;
322	          const m = seg.member;
323	          const r = m.root;
324	          m.openHandles.delete(rec);
325	          if (seg.mgen === m.ownGen && seg.own > 0) {
326	            m.inFlight -= seg.own;
327	          }
328	          for (const link of seg.links) {
329	            const memberLive = seg.mgen === m.ownGen;
330	            const lenderLive =
331	              link.kind === 'pool' ? link.lgen === r.poolGen : link.lgen === link.lender.ownGen;
332	            if (!memberLive || !lenderLive) continue; // a window flip settled it
333	            m.inFlight -= link.units;
334	            m.borrowedInFlight -= link.units;
335	            if (link.kind === 'pool') {
336	              r.poolLinks.delete(link);
337	            } else {
338	              link.lender.lentLinks.delete(link);
339	              link.lender.inFlight -= link.units;
340	              link.lender.lentInFlight -= link.units;
341	            }
342	          }
343	        }
344	      },
345	    };
346	  }
347	
348	  // Commit a fully gathered combo: provisional promises become admitted
349	  // occupations. Pool room was charged at gather time, so poolUsed does not
350	  // move here.
351	  function commitCombo(entry) {
352	    const r = entry.owner.root;
353	    const records = [];
354	    const lenderCleanup = new Set();
355	    for (const seg0 of entry.segs) {
356	      const m = seg0.gate;
357	      const units = seg0.units;
358	      chargeDraw(m, units);
359	      let seg;
360	      if (m === r) {
361	        // The root member's whole slice is its own window and drew the pool
362	        // directly; consume its pool reservation link so it does not survive
363	        // the commit as uncommitted quota.
364	        for (const l0 of seg0.links) {
365	          if (l0.kind === 'pool' && r.poolResv.delete(l0)) r.poolResvUnits -= l0.units;
366	        }
367	        m.usedOwn += units;
368	        m.inFlight += units;
369	        m.resvAsMember.delete(entry);
370	        seg = { member: m, units, own: units, mgen: m.ownGen, links: [] };
371	      } else {
372	        const ownPart = seg0.own;
373	        m.usedOwn += ownPart;
374	        m.pendingOwn -= ownPart;
375	        m.resvAsMember.delete(entry);
376	        m.inFlight += units;
377	        const links = [];
378	        for (const l0 of seg0.links) {
379	          const link = {
380	            kind: l0.kind,
381	            lender: l0.lender,
382	            member: m,
383	            units: l0.units,
384	            lgen: l0.kind === 'pool' ? r.poolGen : l0.lender.ownGen,
385	            mgen: m.ownGen,
386	          };
387	          if (l0.kind === 'pool') {
388	            if (r.poolResv.delete(l0)) r.poolResvUnits -= l0.units;
389	            r.poolLinks.add(link);
390	          } else {
391	            const g = l0.lender;
392	            g.usedOwn += l0.units;
393	            g.pendingLends -= l0.units;
394	            lenderCleanup.add(g);
395	            g.inFlight += l0.units;
396	            g.lentInFlight += l0.units;
397	            link.pgen = r.poolGen; // pool window this lend charged
398	            g.lentLinks.add(link);
399	          }
400	          links.push(link);
401	        }
402	        m.borrowedInFlight += units - ownPart;
403	        seg = { member: m, units, own: ownPart, mgen: m.ownGen, links };
404	      }
405	      const rec = { seg };
406	      m.openHandles.add(rec);
407	      records.push(rec);
408	    }
409	    // One entry may borrow from the same ancestor for several sibling
410	    // members; drop its lender registration once, after every link settled.
411	    for (const g of lenderCleanup) g.resvAsLender.delete(entry);
412	    entry.holdsHeld = false;
413	    entry.segs = null;
414	    return makeHandle(records);
415	  }
416	
417	  // --- Queue entry lifecycle ------------------------------------------------
418	
419	  function detachSignal(entry) {
420	    if (entry.signal !== null) {
421	      entry.signal.removeEventListener('abort', entry.onAbort);
422	      entry.signal = null;
423	    }
424	  }
425	
426	  // One queue entry leaves the queue exactly once, and exactly one of
427	  // granted / refused / expired / cancelled moves as a result.
428	  function settleEntry(entry, outcome) {
429	    if (entry.removed) return;
430	    const ownerRoot = entry.owner.root;
431	    entry.removed = true;
432	    ownerRoot.liveQueued -= 1;
433	    clearTimeout(entry.timer);
434	    detachSignal(entry);
435	    for (const charge of entry.waitCharges) charge.gate.waiting -= charge.units;
436	    if (outcome === 'granted') {
437	      // Both singles and combos arrive here holding a gathered reservation;
438	      // the same commit turns provisional promises into the occupation.
439	      const handle = commitCombo(entry);
440	      entry.owner.granted += 1;
441	      entry.resolve(handle);
442	      return;
443	    }
444	    // Expiry, cancellation and refusal give back any hold; none of those
445	    // outcomes itself counts as a reservation rollback.
446	    releaseHolds(entry);
447	    if (outcome === 'refused') {
448	      entry.owner.refused += 1;
449	      entry.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
450	    } else if (outcome === 'cancelled') {
451	      entry.owner.cancelled += 1;
452	      entry.reject(
453	        new QuotaExceededError('CANCELLED', 'queued request was cancelled before quota was available'),
454	      );
455	    } else {
456	      entry.owner.expired += 1;
457	      entry.reject(
458	        new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
459	      );
460	    }
461	  }
462	
463	  // The wait timer measures real elapsed time, like the baseline. The
464	  // deadline field additionally gates window-flip sweeps when the monotonic
465	  // clock and the wall clock disagree (mocked/frozen clocks).
466	  function armEntry(entry, delay) {
467	    entry.timer = setTimeout(() => {
468	      if (entry.removed) return;
469	      settleEntry(entry, 'expired');
470	    }, Math.max(1, delay));
471	    if (typeof entry.timer.unref === 'function') entry.timer.unref();
472	  }
473	
474	  // At the same moment expiry beats cancellation: an abort arriving once the
475	  // deadline has already passed settles as WAIT_EXPIRED.
476	  function onEntryAbort(entry) {
477	    if (entry.removed) return;
478	    if (entry.deadline <= now()) {
479	      settleEntry(entry, 'expired');
480	    } else {
481	      settleEntry(entry, 'cancelled');
482	    }
483	  }
484	
485	  function recomputeMinDeadline() {
486	    const r = state.root;
487	    let min = Infinity;
488	    const q = r.queue;
489	    for (let i = r.head; i < q.length; i += 1) {
490	      const entry = q[i];
491	      if (!entry.removed && entry.deadline < min) min = entry.deadline;
492	    }
493	    r.minDeadline = min;
494	  }
495	
496	  // Expiry is judged before quota allocation: anything due at or before the
497	  // flip moment expires rather than being granted.
498	  function sweepExpired(t) {
499	    const r = state.root;
500	    if (r.minDeadline > t) return;
501	    let min = Infinity;
502	    for (let i = r.head; i < r.queue.length; i += 1) {
503	      const entry = r.queue[i];
504	      if (entry.removed) continue;
505	      if (entry.deadline <= t) settleEntry(entry, 'expired');
506	      else if (entry.deadline < min) min = entry.deadline;
507	    }
508	    r.minDeadline = min;
509	  }
510	
511	  // Allocation walks arrivals in order against the freshly reset pool. A head
512	  // combo that cannot be gathered whole does not starve later arrivals: a
513	  // later request that fits outright passes it and the combo yields once;
514	  // after yielding twice (cumulatively, across flips) it becomes a hard
515	  // barrier like a non-fitting single. The pass is O(1) per live queue entry:
516	  // a single monotonic counter (serveWave, bumped once per overtaking serve)
517	  // lets each blocked combo derive its yield count without being touched by
518	  // the requests that pass it.
519	  function allocate() {
520	    const r = state.root;
521	    const q = r.queue;
522	    let wave = r.serveWave; // overtakes counted so far, monotonic across passes
523	    let stopWave = Infinity; // earliest wave at which a blocker hardens
524	    let blockerCount = 0; // blocked combos registered earlier in this/prev passes
525	    for (let i = r.head; i < q.length; i += 1) {
526	      const entry = q[i];
527	      if (entry.removed) continue;
528	      if (wave >= stopWave) break;
529	      let served = false;
530	      if (!entry.combo) {
531	        // The pool flip (or a member/ancestor flip) may have reclaimed part
532	        // of the held reservation; release what survived and gather anew.
533	        if (entry.holdsHeld) releaseHolds(entry);
534	        if (tryGatherOne(entry, entry.owner, entry.units)) {
535	          settleEntry(entry, 'granted');
536	          served = true;
537	        } else {
538	          // A single request cannot overtake and is not overtaken: it is an
539	          // ordinary hard barrier against later arrivals, exactly like the
540	          // baseline. No rollback counter moves for a single-gate attempt.
541	          break;
542	        }
543	      } else {
544	        // Combo's turn against the fresh pool: the pool flip reclaimed its
545	        // pool side; release the surviving own-side holds and gather anew.
546	        if (entry.holdsHeld) releaseHolds(entry);
547	        const segs = buildSegs(entry.comboGates, (g) => entry.comboUnits.get(g));
548	        if (tryGather(entry, segs)) {
549	          settleEntry(entry, 'granted');
550	          served = true;
551	        } else {
552	          // Any step short: the plan touched nothing; count one whole
553	          // rollback (no other counter moves) and register a soft barrier.
554	          entry.owner.rolledBack += 1;
555	          if (entry.blockG !== -1) entry.yields += wave - entry.blockG;
556	          entry.blockG = wave;
557	          const hardensAt = wave + (2 - entry.yields);
558	          blockerCount += 1;
559	          if (hardensAt < stopWave) stopWave = hardensAt;
560	        }
561	      }
562	      if (served && blockerCount > 0) wave += 1; // one yield per overtaken blocker
563	    }
564	    r.serveWave = wave;
565	    while (r.head < q.length && q[r.head].removed) r.head += 1;
566	    if (r.head > 32 && r.head * 2 >= q.length) {
567	      r.queue = q.slice(r.head);
568	      r.head = 0;
569	    }
570	  }
571	
572	  // --- Window flips ----------------------------------------------------------
573	
574	  // A non-root own window reclaims quota borrowed FROM this gate, uncommitted
