  const handle = await root.acquireAll([{ gate: a, units: 4 }]); // own 2, parent lend 1, pool 1
  assert.equal(a.stats().inFlight, 4);
  assert.equal(p.stats().inFlight, 3); // its own 2 plus the one lent unit
  handle.release();
