const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let failures = 0;
function check(name, cond, extra) {
  if (!cond) {
    failures += 1;
    console.log(`FAIL: ${name}`, extra ?? '');
  } else {
    console.log(`ok: ${name}`);
  }
}

// 1. Head cancelled -> later requests must be retried and settle (not stall).
{
  const g = createGate({ limit: 2, windowMs: 50, maxWaitMs: 500 });
  await g.acquire(2);
  const ac = new AbortController();
  const e1 = g.acquire(2, ac.signal).then(() => 'g', (e) => e.code);
  const p2 = g.acquire(1).then((h) => 'g', (e) => e.code);
  const p3 = g.acquire(1).then((h) => 'g', (e) => e.code);
  ac.abort();
  check('head cancelled', (await e1) === 'CANCELLED');
  const r2 = await p2;
  const r3 = await p3;
  check('later requests settle after head cancel', r2 === 'g' && r3 === 'g', `${r2} ${r3}`);
  check('waiting drained', g.stats().waiting === 0);
}

// 2. Head expires -> later requests retried.
{
  const g = createGate({ limit: 2, windowMs: 50, maxWaitMs: 500 });
  await g.acquire(2);
  const gShort = g; // same gate; use updateMaxWaitMs trick instead: separate gates
  // Use two gates sharing family to get different maxWaitMs
  const root = createGate({ limit: 2, windowMs: 50, maxWaitMs: 30 });
  const child = createGate({ limit: 2, windowMs: 50, maxWaitMs: 500, parent: root });
  await root.acquire(2);
  const e1 = root.acquire(2).then(() => 'g', (e) => e.code); // expires at 30ms
  const p2 = child.acquire(1).then(() => 'g', (e) => e.code);
  const p3 = child.acquire(1).then(() => 'g', (e) => e.code);
  check('head expires', (await e1) === 'WAIT_EXPIRED');
  const r2 = await p2, r3 = await p3;
  check('later requests settle after head expiry', r2 === 'g' && r3 === 'g', `${r2} ${r3}`);
}

// 3. Head refused via shrink -> later requests retried and settle.
{
  const g = createGate({ limit: 4, windowMs: 50, maxWaitMs: 500 });
  await g.acquire(4);
  const e1 = g.acquire(3).then(() => 'g', (e) => e.code);
  const p2 = g.acquire(1).then(() => 'g', (e) => e.code);
  g.updateLimit(2); // 3 can never fit pool 2 -> refused; 1 survives
  check('head refused by shrink', (await e1) === 'QUOTA_EXCEEDED');
  check('survivor settles', (await p2) === 'g');
}

// 4. Counter conservation under churn: every request settles exactly once.
{
  const g = createGate({ limit: 3, windowMs: 40, maxWaitMs: 120 });
  const results = [];
  const N = 30;
  const ps = [];
  await g.acquire(3); // fill window initially? no - this occupies window 1
  for (let i = 0; i < N; i += 1) {
    const ac = new AbortController();
    const p = g.acquire(1 + (i % 3), ac.signal).then(
      (h) => { results.push('g'); },
      (e) => { results.push(e.code); },
    );
    if (i % 4 === 0) setTimeout(() => ac.abort(), 10 + (i % 5) * 8);
    ps.push(p);
  }
  await Promise.all(ps);
  await sleep(150);
  const s = g.stats();
  const settled = s.granted + s.refused + s.expired + s.cancelled;
  check('all requests settled', settled === N + 1, JSON.stringify(s));
  check('waiting drained after churn', s.waiting === 0, `waiting=${s.waiting}`);
  check('reserved drained after churn', s.reserved === 0, `reserved=${s.reserved}`);
}

// 5. Same-moment: expiry beats grant at the flip.
{
  const g = createGate({ limit: 1, windowMs: 50, maxWaitMs: 50 });
  await g.acquire(1);
  // enqueue at t~0; deadline t+50 == flip time t+50 -> expiry must win
  const r = await g.acquire(1).then(() => 'g', (e) => e.code);
  check('expiry beats grant at same moment', r === 'WAIT_EXPIRED', r);
  check('granted not double counted', g.stats().granted === 1);
}

// 6. Same-moment: cancellation after deadline -> expired; before -> cancelled.
{
  const g = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 40 });
  await g.acquire(1);
  const ac = new AbortController();
  const p = g.acquire(1, ac.signal).then(() => 'g', (e) => e.code);
  await sleep(60); // past deadline; timer already settled it
  ac.abort();
  check('late abort is no-op after expiry', (await p) === 'WAIT_EXPIRED');
  check('cancelled not moved', g.stats().cancelled === 0);
}

// 7. Combo + single queue mixing: head combo cancelled, later single retried.
{
  const root = createGate({ limit: 3, windowMs: 50, maxWaitMs: 500 });
  const a = createGate({ limit: 3, windowMs: 1000, maxWaitMs: 500, parent: root });
  await root.acquire(3);
  const ac = new AbortController();
  const c = root.acquireAll([{ gate: a, units: 2 }], ac.signal).then(() => 'g', (e) => e.code);
  const s1 = root.acquire(1).then(() => 'g', (e) => e.code);
  ac.abort();
  check('combo head cancelled', (await c) === 'CANCELLED');
  check('single behind combo settles', (await s1) === 'g');
}

// 8. reserved and waiting zero in the same snapshot at commit.
{
  const root = createGate({ limit: 3, windowMs: 50, maxWaitMs: 500 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 500, parent: root });
  await root.acquire(2);
  const p = a.acquire(2); // gathers own 2, waits behind? pool 2/3, 2+2>3 -> cannot gather
  check('queued with no hold when ungatherable', a.stats().reserved === 0);
  const h = await p;
  const s = a.stats();
  check('reserved+waiting zero at commit', s.reserved === 0 && s.waiting === 0, JSON.stringify(s));
  h.release();
}

// 9. Many families growth: single acquire latency stays flat-ish (perf smoke).
{
  const root = createGate({ limit: 100000, windowMs: 10000 });
  const gates = [];
  for (let i = 0; i < 200; i += 1) gates.push(createGate({ limit: 100, windowMs: 10000, parent: root }));
  const t0 = process.hrtime.bigint();
  for (let i = 0; i < 2000; i += 1) await gates[i % 200].acquire(1);
  const t1 = process.hrtime.bigint();
  const ms = Number(t1 - t0) / 1e6;
  check('2000 acquires over 200 gates fast', ms < 500, `${ms.toFixed(1)}ms`);
}

// 10. Queue growth: many waiters, flips serve them all, no stall.
{
  const g = createGate({ limit: 5, windowMs: 30, maxWaitMs: 2000 });
  const ps = [];
  for (let i = 0; i < 25; i += 1) ps.push(g.acquire(1).then((h) => 'g', (e) => e.code));
  const rs = await Promise.all(ps);
  check('all 25 queued singles granted across flips', rs.every((r) => r === 'g'), rs.filter((r) => r !== 'g').join(','));
  check('granted count exact', g.stats().granted === 25, `${g.stats().granted}`);
}

console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);

