  else console.log(`ok: ${name}`);
}

// A. Queued single's OWN-gate window flips before the pool flip: its own-slice
//    hold is reclaimed; it must still settle (re-gather) at the pool flip.
{
  const root = createGate({ limit: 4, windowMs: 120, maxWaitMs: 2000 });
  const a = createGate({ limit: 2, windowMs: 30, maxWaitMs: 2000, parent: root });
  await root.acquire(3); // pool 3/4
  const pBlock = root.acquire(2); // 3+2>4 queues (head)
  const pMine = a.acquire(2); // own 2 gathers (3+2=5>4? no: poolUsed 3, +2 = 5 > 4 -> cannot gather)
  // Actually 3+2=5 > 4 so pMine cannot gather either. Adjust: use units 1.
  const r1 = await pBlock.then(() => 'g', (e) => e.code);
  const r2 = await pMine.then(() => 'g', (e) => e.code);
  check('A: both settle', r1 === 'g' && r2 === 'g', `${r1} ${r2}`);
}

// B. Lender-side pendingLends released when the queued borrower expires.
{
  const root = createGate({ limit: 10, windowMs: 10000, maxWaitMs: 5000 });
  const p = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: root });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 40, parent: p });
  await root.acquire(6); // pool 6/10
  const pBlock = root.acquire(5); // 6+5>10 queues (head, blocks all)
  // a needs 4: own 2 + lend 2 from p = 4; 6+4=10 gathers, queued behind blocker
  const pExp = a.acquire(4).then(() => 'g', (e) => e.code);
  check('B: lend reserved', p.stats().reserved === 2, `${p.stats().reserved}`);
  check('B: own reserved', a.stats().reserved === 2);
  const r = await pExp;
  check('B: expired', r === 'WAIT_EXPIRED', r);
  check('B: lender hold released', p.stats().reserved === 0, `${p.stats().reserved}`);
  check('B: member hold released', a.stats().reserved === 0);
  check('B: root pool hold released', root.stats().reserved === 0);
  pBlock.catch(() => {});
}

// C. Lender-side hold released when the queued borrower is cancelled.
{
  const root = createGate({ limit: 10, windowMs: 10000, maxWaitMs: 5000 });
  const p = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: root });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: p });
  await root.acquire(6);
  const pBlock = root.acquire(5); // head blocker
  const ac = new AbortController();
  const pC = a.acquire(4, ac.signal).then(() => 'g', (e) => e.code);
  check('C: lend reserved', p.stats().reserved === 2);
  ac.abort();
  check('C: cancelled', (await pC) === 'CANCELLED');
  check('C: lender hold released', p.stats().reserved === 0);
  check('C: member hold released', a.stats().reserved === 0);
  pBlock.catch(() => {});
}

