  const leaf = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 5000, parent: mid });
  const newRoot = createGate({ limit: 6, windowMs: 50, maxWaitMs: 5000 });
  await oldRoot.acquire(4); // old pool 4/6
  const pBlock = oldRoot.acquire(3); // 4+3>6 queues (head)
  const pLeaf = leaf.acquire(2); // own 1 + lend 1 from mid; 4+2=6 gathers, queued
