{
  const root = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: root });
  const b = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: root });
  await root.acquire(3);
  const p = root.acquireAll([{ gate: a, units: 2 }, { gate: b, units: 2 }]).then(() => 'g', (e) => e.code);
  check('F: member waiting charged', a.stats().waiting === 2 && b.stats().waiting === 2);
  root.updateLimit(3); // total 4 > 3 -> refuse whole combo
  check('F: combo refused', (await p) === 'QUOTA_EXCEEDED');
  check('F: waiting drained', a.stats().waiting === 0 && b.stats().waiting === 0);
  check('F: reserved drained', a.stats().reserved === 0 && b.stats().reserved === 0);
}

// G. Expiry ordering vs cancellation vs grant, all landing on the flip tick.
{
  const g = createGate({ limit: 2, windowMs: 60, maxWaitMs: 60 });
  await g.acquire(2);
  const ac = new AbortController();
  const e1 = g.acquire(1, ac.signal).then(() => 'g', (e) => e.code);
