  check('G: both expire at flip, none granted early', r1 === 'WAIT_EXPIRED' && r2 === 'WAIT_EXPIRED', `${r1} ${r2}`);
  check('G: granted stays 1', g.stats().granted === 1, `${g.stats().granted}`);
}

// H. updateMaxWaitMs on a gate whose waiters hold lends: deadline move keeps holds.
{
  const root = createGate({ limit: 4, windowMs: 10000, maxWaitMs: 5000 });
  const p = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: root });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: p });
  await root.acquire(3); // pool 3/4
  const pBlock = root.acquire(2); // queues (head)
  const pMine = a.acquire(3); // own 2 + lend 1; 3+3=6>4 cannot gather -> no hold
  a.updateMaxWaitMs(60); // retime; pMine still queued
  const r = await pMine.then(() => 'g', (e) => e.code);
  check('H: retimed waiter expires', r === 'WAIT_EXPIRED', r);
  check('H: no leaked holds', a.stats().reserved === 0 && p.stats().reserved === 0 && root.stats().reserved === 0);
  pBlock.catch(() => {});
}

// I. A queued combo straddling a reparent is refused whole; later arrivals retry.
{
  const oldRoot = createGate({ limit: 5, windowMs: 50, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const b = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const newRoot = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  await oldRoot.acquire(4);
  const pSplit = oldRoot.acquireAll([{ gate: a, units: 1 }, { gate: b, units: 1 }]).then(() => 'g', (e) => e.code);
  const pBehind = oldRoot.acquire(1).then(() => 'g', (e) => e.code);
  a.reparent(newRoot); // split combo refused
  check('I: split combo refused', (await pSplit) === 'QUOTA_EXCEEDED');
  check('I: later arrival still settles', (await pBehind) === 'g');
}

// J. Repeated flips with nothing queued: no counter drift.
{
  const g = createGate({ limit: 2, windowMs: 30, maxWaitMs: 100 });
  await sleep(100);
  const s = g.stats();
  check('J: idle flips drift nothing', s.granted === 0 && s.inFlight === 0 && s.reserved === 0 && s.waiting === 0);
}

clearInterval(keepAlive);
console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);

