  check('A: release drains', root.stats().inFlight === 0 && a.stats().inFlight === 0);
}

// B. acquireAll called on a CHILD gate with members across the family.
{
  const root = createGate({ limit: 6, windowMs: 1000 });
  const a = createGate({ limit: 2, windowMs: 1000, parent: root });
  const b = createGate({ limit: 2, windowMs: 1000, parent: root });
  const h = await a.acquireAll([{ gate: a, units: 1 }, { gate: b, units: 1 }]);
  check('B: child-called combo granted on caller', a.stats().granted === 1, `${a.stats().granted}`);
  check('B: members occupied', a.stats().inFlight === 1 && b.stats().inFlight === 1);
  h.release();
}

// C. Child-called queued combo: settles at pool flip, counters on the caller.
{
  const root = createGate({ limit: 3, windowMs: 50, maxWaitMs: 1000 });
  const a = createGate({ limit: 2, windowMs: 1000, maxWaitMs: 1000, parent: root });
  const b = createGate({ limit: 2, windowMs: 1000, maxWaitMs: 1000, parent: root });
