  const r = await p;
  check('C: granted at flip', r === 'g', r);
  check('C: caller granted count', a.stats().granted === 1);
  check('C: waiting drained', a.stats().waiting === 0 && b.stats().waiting === 0);
}

// D. Huge maxWaitMs must not expire early (setTimeout 2^31 overflow).
{
  const g = createGate({ limit: 1, windowMs: 60, maxWaitMs: 3_000_000_000 });
